script:
// Script Name: Hide Incident Tabs
frappe.ui.form.on('Incident', {
    refresh: function(frm) {
        // Hide tabs based on user roles and document status
        hide_tabs_based_on_conditions(frm);
    },
    
    status: function(frm) {
        // Re-run visibility checks when status changes
        hide_tabs_based_on_conditions(frm);
    },
    
    severity: function(frm) {
        // Re-run visibility checks when severity changes
        hide_tabs_based_on_conditions(frm);
    }
});

function hide_tabs_based_on_conditions(frm) {
    // Check if user has incident management roles
    let is_incident_responder = frappe.user.has_role("Incident Responder");
    let is_incident_manager = frappe.user.has_role("Incident Manager");
    let has_incident_role = is_incident_responder || is_incident_manager;
    
    // Get current document status and severity
    let status = frm.doc.status || "";
    let severity = frm.doc.severity || "";
    
    // Investigation tab - show only for In Progress/Resolved status and authorized roles
    let show_investigation = has_incident_role && (status === "In Progress" || status === "Resolved");
    frm.toggle_display("investigation_tab", show_investigation);
    
    // Resolution tab - show for In Progress/Resolved/Closed status and authorized roles
    let show_resolution = has_incident_role && (status === "In Progress" || status === "Resolved" || status === "Closed");
    frm.toggle_display("resolution_tab", show_resolution);
    
    // Impact Assessment tab - show only for Critical/High severity and authorized roles
    let show_impact = has_incident_role && (severity === "Critical" || severity === "High");
    frm.toggle_display("impact_assessment_tab", show_impact);
    
    // Categorization tab - always hide
    frm.toggle_display("categorization_tab", false);
    
    // Alternative method using set_df_property if toggle_display doesn't work
    setTimeout(function() {
        if (frm.fields_dict.investigation_tab) {
            frm.set_df_property("investigation_tab", "hidden", !show_investigation);
        }
        if (frm.fields_dict.resolution_tab) {
            frm.set_df_property("resolution_tab", "hidden", !show_resolution);
        }
        if (frm.fields_dict.impact_assessment_tab) {
            frm.set_df_property("impact_assessment_tab", "hidden", !show_impact);
        }
        if (frm.fields_dict.categorization_tab) {
            frm.set_df_property("categorization_tab", "hidden", true);
        }
    }, 100);
}

frappe.ui.form.on('Incident', {
    onload: function(frm) {
        // Check if user has specific role
        if (frappe.user.has_role('Incident Reporter')) {
            // Hide the sidebar
            $('.layout-side-section').hide();
            // Or hide specific sidebar sections
            $('.form-sidebar').hide();
            
            // Hide the comments and activity section
            $('.form-footer').hide();
            $('.timeline-content').hide();
            $('.comment-box').hide();
            $('.timeline-item').hide();
            $('.activity-timeline').hide();
            
            // Hide the entire bottom section with comments and activity
            $('[data-fieldtype="Comment"]').hide();
            $('.timeline-section').hide();
            $('.communications-section').hide();
            $('.form-timeline').hide();
            
            // More specific targeting - avoid hiding tab content
            $('.form-comments-section').hide();
            $('.timeline-message-box').hide();
        }
    },
    
    refresh: function(frm) {
        // Also hide on refresh with a small delay to ensure DOM is ready
        if (frappe.user.has_role('Incident Reporter')) {
            setTimeout(function() {
                $('.layout-side-section').hide();
                $('.form-sidebar').hide();
                $('.form-footer').hide();
                $('.timeline-content').hide();
                $('.comment-box').hide();
                $('.timeline-item').hide();
                $('.activity-timeline').hide();
                $('[data-fieldtype="Comment"]').hide();
                $('.timeline-section').hide();
                $('.communications-section').hide();
                $('.form-timeline').hide();
                $('.form-comments-section').hide();
                $('.timeline-message-box').hide();
                
                // Target specific elements without affecting tabs
                $('h6:contains("Comments")').closest('.section-head').next('.section-body').hide();
                $('h6:contains("Comments")').closest('.section-head').hide();
                $('h6:contains("Activity")').closest('.section-head').next('.section-body').hide();
                $('h6:contains("Activity")').closest('.section-head').hide();
                
                $('.timeline-head').hide();
                $('.comment-input-container').hide();
                
                // Hide only the timeline wrapper, not tab content
                $('.timeline-wrapper').hide();
                $('.form-timeline-wrapper').hide();
            }, 200);
        }
    }
});

frappe.ui.form.on('Incident', {
    refresh: function(frm) {
        // Check if current user has Incident Manager role
        const hasSystemManagerRole = frappe.user.has_role('Incident Manager');

        if (!hasSystemManagerRole) {
            // Hide assignments section only for non-Incident Managers
            $('.form-assignments').hide();

            // Make assign_to field read-only for non-Incident Managers
            frm.set_df_property('assign_to', 'read_only', 1);
        } else {
            // Ensure assignments are visible for Incident Managers
            $('.form-assignments').show();

            // Make assign_to field editable for Incident Managers
            frm.set_df_property('assign_to', 'read_only', 0);
        }
    }
});

frappe.ui.form.on('Incident', {
    refresh: function(frm) {
        // Check if current user has Incident Reporter role
        const hasIncidentReporterRole = frappe.user.has_role('Incident Reporter');

        if (hasIncidentReporterRole) {
            // Hide activity section for Incident Reporters
            $('.timeline-items').hide();
            $('.form-timeline').hide();
            $('.timeline-head').hide();
        } else {
            // Ensure activity section is visible for other users
            $('.timeline-items').show();
            $('.form-timeline').show();
            $('.timeline-head').show();
        }
    }
});

frappe.ui.form.on('Incident', {
    refresh: function(frm) {
        // Check if current user has Incident Manager role
        const hasSystemManagerRole = frappe.user.has_role('Incident Manager');

        if (!hasSystemManagerRole) {
            // Hide share button only for non-Incident Managers
            $('.form-shared').hide();
        } else {
            // Ensure share button is visible for Incident Managers
            $('.form-shared').show();
        }
    }
});

frappe.listview_settings['Incident'] = {
    refresh: function(listview) {
        // Check if current user has 'Incident Reporter' role
        if (frappe.user_roles.includes('Incident Reporter')) {
            // Hide the avatar/assigned icon for incident reporters only
            $(".avatar-small").hide(); 
            // Hide the comment count if it's part of the assigned icon
            $(".comment-count").hide(); 
        }
    }
};
